const input = $json.body ?? $json;
const required = ['caller_name', 'phone', 'address_or_zip', 'service_type', 'issue_summary', 'urgency', 'preferred_window', 'existing_customer'];
const missing = required.filter((key) => input[key] === undefined || input[key] === null || input[key] === '');
if (missing.length) {
  return [{ json: { status: 'needs_human', missing_fields: missing, message: 'The service request is missing required information and needs human follow-up.' } }];
}
const confirmationReference = `DEMO-${Date.now().toString().slice(-6)}`;
return [{ json: { status: 'received', confirmation_reference: confirmationReference, message: 'The service request was received for human scheduling review.', lead: input } }];
